function contactItems(settings){const out=[],phone=first(settings.support_phone),email=first(settings.support_email),wa=first(settings.whatsapp_url);if(phone)out.push({label:'الدعم',value:phone,href:`tel:${phone.replace(/\s+/g,'')}`});if(wa)out.push({label:'WhatsApp',value:wa.replace(/^https?:\/\/(www\.)?wa\.me\//i,'').replace(/^https?:\/\/(www\.)?api\.whatsapp\.com\/send\?phone=/i,''),href:safeUrl(wa)});if(email)out.push({label:'Email',value:email,href:`mailto:${email}`});[['Facebook','facebook_url','facebook_active'],['Instagram','instagram_url','instagram_active'],['Telegram','telegram_url','telegram_active'],['TikTok','tiktok_url','tiktok_active']].forEach(([label,key,activeKey])=>{const url=first(settings[key]);if(url&&settings[activeKey]!==false)out.push({label,value:label,href:safeUrl(url)})});return out.filter(x=>x.value)}
function contactsHtml(settings){const list=contactItems(settings);if(!list.length)return'';return `<footer class="footer-contacts"><div class="footer-title">KINTO Contact</div><div class="footer-links">${list.map(x=>x.href?`<a href="${esc(x.href)}" target="_blank" rel="noopener"><b>${esc(x.label)}</b><span dir="ltr">${esc(x.value)}</span></a>`:`<span><b>${esc(x.label)}</b><span dir="ltr">${esc(x.value)}</span></span>`).join('')}</div></footer>`}
